// Filters for the extension tables generated by the IG publisher (CrossViewRenderer.buildExtensionTable).
//
// A page can contain several of these tables (e.g. extensions-datatypes.html has one per type), and
// each table fragment loads this script, so:
//  - every table is handled independently: its controls carry data-filter="<key>" and are found
//    inside the table (<table data-filter-table="<prefix>">), not by id
//  - the setup only runs once, however many times the script is loaded
//  - saved filter state is per table (localStorage key tableFilter_<prefix>_<key>)
(function () {
    if (window.fhirExtensionTableFilters) {
        return;
    }
    window.fhirExtensionTableFilters = true;

    // column index of each text filter
    const COLUMNS = { identity: 0, card: 1, type: 2, context: 3, wg: 4, status: 5 };
    const KEYS = ['identity', 'card', 'type', 'context', 'wg', 'status', 'hideUnchanged'];

    function storageKey(prefix, key) {
        return `tableFilter_${prefix}_${key}`;
    }

    function saveFilterState(prefix, key, value) {
        try {
            localStorage.setItem(storageKey(prefix, key), JSON.stringify(value));
        } catch (e) {
            console.warn('Could not save filter state to localStorage:', e);
        }
    }

    function loadFilterState(prefix, key, defaultValue) {
        try {
            const stored = localStorage.getItem(storageKey(prefix, key));
            return stored ? JSON.parse(stored) : defaultValue;
        } catch (e) {
            console.warn('Could not load filter state from localStorage:', e);
            return defaultValue;
        }
    }

    function tableFor(prefix) {
        return document.querySelector(`table[data-filter-table="${prefix}"]`);
    }

    function applyFilters(table) {
        const prefix = table.getAttribute('data-filter-table');
        const hideUnchanged = loadFilterState(prefix, 'hideUnchanged', false);
        const filters = Object.keys(COLUMNS)
            .map(key => ({ value: String(loadFilterState(prefix, key, '')).toLowerCase(), cellIndex: COLUMNS[key] }))
            .filter(f => f.value);

        table.querySelectorAll('tr.data-row').forEach(row => {
            const cells = row.querySelectorAll('td');
            let shouldShow = filters.every(f =>
                !cells[f.cellIndex] || cells[f.cellIndex].textContent.toLowerCase().includes(f.value));
            if (hideUnchanged && row.getAttribute('data-change') !== 'true') {
                shouldShow = false;
            }
            row.classList.toggle('hidden-row', !shouldShow);
        });
    }

    function setUpTable(table) {
        const prefix = table.getAttribute('data-filter-table');
        table.querySelectorAll('[data-filter]').forEach(control => {
            const key = control.getAttribute('data-filter');
            if (control.type === 'checkbox') {
                control.checked = loadFilterState(prefix, key, false);
                control.addEventListener('change', function () {
                    saveFilterState(prefix, key, this.checked);
                    applyFilters(table);
                });
            } else {
                control.value = loadFilterState(prefix, key, '');
                control.addEventListener('input', function () {
                    saveFilterState(prefix, key, this.value);
                    applyFilters(table);
                });
            }
        });
        applyFilters(table);
    }

    function setUpAll() {
        document.querySelectorAll('table[data-filter-table]').forEach(setUpTable);
    }

    // clears the filters of one table (the button under each table passes its prefix)
    window.clearAllFilters = function (prefix) {
        const table = tableFor(prefix);
        if (!table) {
            return;
        }
        table.querySelectorAll('[data-filter]').forEach(control => {
            if (control.type === 'checkbox') {
                control.checked = false;
            } else {
                control.value = '';
            }
        });
        KEYS.forEach(key => {
            try {
                localStorage.removeItem(storageKey(prefix, key));
            } catch (e) {
                console.warn('Could not clear filter from localStorage:', e);
            }
        });
        applyFilters(table);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', setUpAll);
    } else {
        setUpAll();
    }
})();
